CREATE OR REPLACE FUNCTION public.evaluation_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE campaign evaluation_campaign; held numeric;
BEGIN
 PERFORM pg_advisory_xact_lock(620313);
 SELECT * INTO campaign FROM evaluation_campaign WHERE id='t_62fc313f';
 IF campaign.id IS NULL OR clock_timestamp()>=campaign.deadline OR clock_timestamp()>=campaign.expires_at THEN
  RAISE EXCEPTION 'evaluation_campaign_expired_or_inactive';
 END IF;
 IF TG_TABLE_NAME='run_successors' THEN RAISE EXCEPTION 'evaluation_successors_forbidden'; END IF;
 IF TG_TABLE_NAME='run_configurations' THEN
  IF NEW.data->>'grant_id'<>'step4-a01-t62fc313f' OR (SELECT count(*) FROM run_configurations)>=1 THEN
   RAISE EXCEPTION 'evaluation_run_limit';
  END IF;
 ELSIF TG_TABLE_NAME='responses_events' THEN
  IF NEW.kind NOT IN ('count_send','dispatch','read','cancel') THEN RETURN NEW; END IF;
  IF NEW.kind='cancel' THEN RAISE EXCEPTION 'evaluation_cancellation_forbidden'; END IF;
  SELECT coalesce(sum(CASE WHEN kind='dispatch' THEN (data->>'reserved_cost_usd')::numeric WHEN kind IN ('count_send','read') THEN .01 ELSE 0 END),0) INTO held FROM responses_events;
  held=held+CASE WHEN NEW.kind='dispatch' THEN coalesce((NEW.data->>'reserved_cost_usd')::numeric,1) ELSE .01 END;
  IF held>campaign.allocation THEN RAISE EXCEPTION 'evaluation_cost_limit'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.evaluation_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE campaign evaluation_campaign; held numeric;
BEGIN
 PERFORM pg_advisory_xact_lock(605701);
 SELECT * INTO campaign FROM evaluation_campaign WHERE id='t_ba6057bd';
 IF campaign.id IS NULL OR clock_timestamp()>=campaign.deadline OR clock_timestamp()>=campaign.expires_at THEN
  RAISE EXCEPTION 'evaluation_campaign_expired_or_inactive';
 END IF;
 IF TG_TABLE_NAME='run_successors' AND (SELECT count(*) FROM run_successors)>=4 THEN RAISE EXCEPTION 'evaluation_successor_limit'; END IF;
 IF TG_TABLE_NAME='run_configurations' THEN
  IF NEW.data->>'grant_id' NOT IN ('step4-continuation-tba6057bd','step4-continuation-tba6057bd-successor','step4-continuation-tba6057bd-sustained','step4-continuation-tba6057bd-scheduled') OR (SELECT count(*) FROM run_configurations)>=12 THEN
   RAISE EXCEPTION 'evaluation_run_limit';
  END IF;
 ELSIF TG_TABLE_NAME='responses_events' THEN
  IF NEW.kind NOT IN ('count_send','dispatch','read','cancel') THEN RETURN NEW; END IF;
  IF NEW.kind='cancel' THEN RAISE EXCEPTION 'evaluation_cancellation_forbidden'; END IF;
  SELECT coalesce(sum(CASE WHEN kind='dispatch' THEN (data->>'reserved_cost_usd')::numeric WHEN kind IN ('count_send','read') THEN .01 ELSE 0 END),0) INTO held FROM responses_events;
  held=held+CASE WHEN NEW.kind='dispatch' THEN coalesce((NEW.data->>'reserved_cost_usd')::numeric,1) ELSE .01 END;
  IF held>campaign.allocation THEN RAISE EXCEPTION 'evaluation_cost_limit'; END IF;
 END IF;
 RETURN NEW;
END $function$
